#include <iostream>
#include <vector>

void RotateLeft(std::vector<int>& values, long long k);

int main()
{
    int n;
    long long k;
    while (std::cin >> n >> k)
    {
        std::vector<int> values(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }
        RotateLeft(values, k);
        for (int i = 0; i < n; i++)
        {
            std::cout << values[i] << (i + 1 < n ? " " : "");
        }
        std::cout << "\n";
    }
    return 0;
}

