"""Random vectors with a shift that is sometimes negative and sometimes many
multiples of the size."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 9)
    k = rng.choice([rng.randint(-3, 3), rng.randint(-40, 40),
                    rng.randint(-10**12, 10**12)])
    values = [rng.randint(-9, 9) for _ in range(n)]
    return {"name": "%d elements, k = %d #%d" % (n, k, index),
            "stdin": "%d %d\n%s\n" % (n, k, " ".join(map(str, values)))}
